import pathlib,json,hashlib,numpy as np,math
O=pathlib.Path(__file__).resolve().parent;N=O.parent;ROOT=N.parents[4];read=lambda p:json.loads(p.read_text());sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
